const { useState } = React;

function slowDouble(number) {
  let result = 0;
  for (let i = 0; i < 3000000; i += 1) result = number * 2;
  return result;
}
function App() {
  const [count, setCount] = useState(1);
  const [name, setName] = useState('');
  const start = performance.now();
  const doubled = slowDouble(count);
  console.log('계산 시간:', performance.now() - start, 'ms');

  return (
    <main>
      <button type="button" onClick={() => setCount(count + 1)}>count {count}</button>
      <input value={name} onChange={(event) => setName(event.currentTarget.value)} placeholder="이름" />
      <p>계산 결과: {doubled}</p>
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

